CREATE DATABASE IF NOT EXISTS sewa_iphone CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sewa_iphone;
CREATE TABLE tb_users (id_user INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','user') NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tb_pelanggan (id_pelanggan INT AUTO_INCREMENT PRIMARY KEY, id_user INT NOT NULL UNIQUE, nama_lengkap VARCHAR(100) NOT NULL, nomor_nik VARCHAR(30) NOT NULL UNIQUE, nomor_wa VARCHAR(25) NOT NULL, jenis_jaminan ENUM('KTP','Kartu Pelajar','SIM','Paspor','Kartu Identitas Lainnya') NULL, foto_jaminan VARCHAR(255) NULL, alamat TEXT NOT NULL, FOREIGN KEY (id_user) REFERENCES tb_users(id_user) ON DELETE CASCADE);
CREATE TABLE tb_iphone_model (id_model INT AUTO_INCREMENT PRIMARY KEY, nama_model VARCHAR(100) NOT NULL, penyimpanan VARCHAR(20) NOT NULL, harga_sewa_per_hari DECIMAL(12,2) NOT NULL);
CREATE TABLE tb_unit_iphone (id_unit INT AUTO_INCREMENT PRIMARY KEY, id_model INT NOT NULL, nomor_seri VARCHAR(100) NOT NULL UNIQUE, warna VARCHAR(50) NOT NULL, foto VARCHAR(255) NULL, status ENUM('ready','disewa','maintenance','hilang') NOT NULL DEFAULT 'ready', FOREIGN KEY (id_model) REFERENCES tb_iphone_model(id_model) ON DELETE RESTRICT);
CREATE TABLE tb_penyewaan (id_sewa INT AUTO_INCREMENT PRIMARY KEY, id_pelanggan INT NOT NULL, id_unit INT NOT NULL, jenis_jaminan VARCHAR(50) NOT NULL, foto_jaminan VARCHAR(255) NULL, tgl_sewa DATETIME NOT NULL, tgl_kembali_rencana DATETIME NOT NULL, tgl_kembali_aktual DATETIME NULL, tarif_denda_per_jam DECIMAL(12,2) NOT NULL DEFAULT 10000, total_denda DECIMAL(12,2) NOT NULL DEFAULT 0, status_transaksi ENUM('pending','berjalan','selesai','bermasalah') NOT NULL DEFAULT 'pending', FOREIGN KEY (id_pelanggan) REFERENCES tb_pelanggan(id_pelanggan), FOREIGN KEY (id_unit) REFERENCES tb_unit_iphone(id_unit));
